function policy(g,{tier='D',routine='REST',move=false,style=0}={}){const k=g.event.kind;return k==='FORMATION'?g.event.choices[g.formation]:k==='ENTRY'?g.event.choices.find(c=>c.profile.division===tier)??g.event.choices.at(-1):k==='ROUTINE'?pick(g,'routine:'+routine):k==='PLAN'?g.event.choices[style]:k==='RECOVERY'?pick(g,'recovery:READ'):k==='DECISIVE'?pick(g,'decisive:safe'):move&&['INTEREST','CONTACT','OFFER'].includes(k)?g.event.choices[0]:pick(g,'market:stay')??g.event.choices[0];}
function advance(g,kind,opts={}){let guard=0;while(g.phase!=='DONE'&&g.event.kind!==kind){assert(choose(g,policy(g,opts).id),g.event.kind);assert(++guard<180);}assert.equal(g.event.kind,kind);return g;}
function sums(ms){return ms.reduce((s,m)=>{if(m.minutes){s.apps++;s.starts+=+m.started;s.minutes+=m.minutes;s.goals+=m.goals;s.assists+=m.assists;s.ratingSum+=m.rating;}return s;},{apps:0,starts:0,minutes:0,goals:0,assists:0,ratingSum:0});}
function finite(x){if(typeof x==='number')assert(Number.isFinite(x));else if(x&&typeof x==='object')Object.values(x).forEach(finite);}
function calendar(g){if(['FORMATION','ENTRY'].includes(g.phase))return;if(g.nationalRevision===1)assert.equal(g.calendarRevision,1);assert.equal(g.schedule.length,18);assert.equal(new Set(g.schedule).size,9);for(const id of g.schedule){assert.notEqual(id,g.clubId);assert.equal(g.schedule.filter(x=>x===id).length,2);}if(g.scheduleNationalRevision!==1)return;const c=byId(g.clubId);assert.equal(g.scheduleDivision,c.division);for(const id of g.schedule)assert.equal(byId(id).division,c.division);if(c.division==='D'){assert.equal(g.scheduleGroup,c.group);const pair='A'+(Number(c.group.slice(1))%2?Number(c.group.slice(1))+1:Number(c.group.slice(1))-1),ids=[...new Set(g.schedule)];assert.equal(ids.filter(id=>byId(id).group===c.group).length,5);assert.equal(ids.filter(id=>byId(id).group===pair).length,4);if(['PLAN','RIVALRY'].includes(g.event.kind))assert.match(g.event.body+g.event.title,/experimental|amostra/i);}else assert(g.scheduleGroup===undefined||g.scheduleGroup===null);}
function finish(g,opts={},observer=()=>{}){let guard=0;while(g.phase!=='DONE'){assert(validGame(g),g.event.kind);finite(g);calendar(g);observer(g);const loaded=clone(g),c=policy(g,opts),raw=JSON.stringify(g);assert(c,g.event.kind);assert.equal(choose(g,'forged@'+g.serial),false);assert.equal(JSON.stringify(g),raw);assert(choose(g,c.id),g.event.kind);assert(choose(loaded,c.id));assert.deepEqual(g,loaded);assert(++guard<180);}assert(validGame(g));calendar(g);const end=g.careerEndAge??21;assert.equal(g.age,end);assert.equal(g.playedMatches.length,(end-18)*18);assert.equal(g.yearStats.length,end-18);assert.equal(g.choicesLog.filter(c=>c.kind==='INTEREST').length,opts.marketWindows??end-19);assert.equal(g.objectiveHistory.length,(end-18)*3);assert.deepEqual(g.totalstats,sums(g.playedMatches));for(const y of g.yearStats){const ms=g.playedMatches.filter(m=>m.season===y.season);assert.equal(ms.length,18);assert.equal(new Set(ms.map(m=>m.opponentId)).size,9);assert.deepEqual(Object.fromEntries(Object.keys(g.totalstats).map(k=>[k,y[k]])),sums(ms));}return g;}
check('all116 C D ids official memberships and regional groups pinned; old44 strengths and names intact',()=>{assert.equal(CLUB_CATALOG_VERSION,'brasil-abcd-2026');assert.match(CLUB_SOURCES.C,/cbf/i);assert.match(CLUB_SOURCES.D,/cbf/i);assert.equal(CLUBS.length,156);assert.equal(new Set(CLUBS.map(c=>c.id)).size,156);assert.equal(new Set(CLUBS.map(c=>c.name)).size,156);assert.deepEqual(CLUBS.filter(c=>['C','D'].includes(c.division)).map(c=>({id:c.id,state:c.state,division:c.division,group:c.group??null})).sort((a,b)=>a.id.localeCompare(b.id)),EXPECTED_CD);for(let n=1;n<=16;n++)assert.equal(CLUBS.filter(c=>c.division==='D'&&c.group==='A'+n).length,6);for(const old of OLD06.catalog){const c=byId(old.id);for(const k of ['name','level','prestige','state','color'])assert.deepEqual(c[k],old[k],old.id+' '+k);if(old.division!=='REGIONAL')assert.equal(c.division,old.division);}assert.equal(byId('sao-luiz').division,'D');assert.equal(byId('brasil-pelotas').division,'D');assert.equal(byId('caxias').division,'C');assert.equal(byId('ypiranga').division,'C');metrics.catalog={A:20,B:20,C:20,D:96,regionalGroups:16,preservedIdentities:44};});
check('allfour tiers offered and signed with actual frozen salary structure rivalry forecasts',()=>{const seen=new Set(),rows=[];for(const {id:position}of POSITIONS)for(let seed=1;seed<=64;seed++){const g=advance(createGame('ENTRY público CD',position,seed),'ENTRY');assert.equal(g.entryOffers.length,3);assert.deepEqual(g.entryOffers.slice(0,2).map(p=>p.division),['D','C']);assert.equal(g.entryOffers[2].division,overall(g)>=50?'A':'B');for(const p of g.entryOffers){const raw=JSON.stringify(g);assert.deepEqual(projectProfile(g,p.clubId),p);assert.equal(JSON.stringify(g),raw);assert(p.monthly>0&&p.trainingQuality>0&&p.starterChance>0&&p.starterChance<1);const x=clone(g);assert(choose(x,pick(x,'entry:'+p.clubId).id));assert.equal(x.salary,p.monthly);assert.equal(x.clubProject.trainingQuality,p.trainingQuality);assert.equal(x.rival.quality,p.rivalQuality);assert.equal(x.clubProject.division,p.division);calendar(x);seen.add(p.division);rows.push({tier:p.division,pay:p.monthly,training:p.trainingQuality,chance:p.starterChance});}}const aspirational=createGame('A elegível sintético','ST',17);for(let n=0;n<2;n++)assert(choose(aspirational,aspirational.event.choices[0].id));for(const k of Object.keys(aspirational.skills))aspirational.skills[k]=65;assert(validGame(aspirational));advance(aspirational,'ENTRY');assert(overall(aspirational)>=50);assert.equal(aspirational.entryOffers[2].division,'A');const a=aspirational.entryOffers[2];assert(choose(aspirational,pick(aspirational,'entry:'+a.clubId).id));assert.equal(aspirational.salary,a.monthly);assert.equal(aspirational.clubProject.trainingQuality,a.trainingQuality);calendar(aspirational);seen.add('A');assert.deepEqual(seen,new Set(['D','C','B','A']));metrics.entries={branches:rows.length,tiers:[...seen],examples:rows.slice(0,6)};});
check('C calendars reach nineteen peers and D sample retains paired regional eligibility',()=>{const seen=new Map(),groupsSeen=new Set();let samples=0;for(let seed=1;seed<=512;seed++)for(const tier of ['C','D']){const g=advance(createGame('Calendário CD','ST',seed),'PLAN',{tier});calendar(g);samples++;if(tier==='D')groupsSeen.add(byId(g.clubId).group);else{const bank=seen.get(g.clubId)??new Set();g.schedule.forEach(id=>bank.add(id));seen.set(g.clubId,bank);}}assert.equal(groupsSeen.size,16);assert(seen.size);for(const[id,ids]of seen){assert.equal(ids.size,19,id);assert.deepEqual(ids,new Set(CLUBS.filter(c=>c.division==='C'&&c.id!==id).map(c=>c.id)));}metrics.calendars={samples,DGroups:groupsSeen.size,COrigins:seen.size,opponentsPerC:19};});
const careers=[];
check('128 lower division careers eight roles 126 fixtures and exact full JSON replay',()=>{const observed=new Set();for(const {id:position}of POSITIONS)for(let seed=1;seed<=8;seed++)for(const tier of ['C','D']){const g=createGame('Carreira CD',position,(Math.imul(seed,2654435761)+17)>>>0);finish(g,{tier,move:seed%2===0,style:seed%3},x=>{if(x.event.kind==='INTEREST')observed.add(x.market.length?'CONTACT':'SILENT');if(x.event.kind==='ASSESSMENT_RESULT')observed.add('FAILED');});const replay=createGame(g.name,g.position,g.seed);for(const c of g.choicesLog)assert(choose(replay,c.id));assert.deepEqual(replay,g);careers.push(g);}metrics.careers={count:careers.length,fixtures:careers.length*126,silent:careers.filter(g=>g.marketHistory?.some(w=>!w.contacts.length)).length,failed:careers.filter(g=>g.choicesLog.some(c=>c.kind==='ASSESSMENT_RESULT')).length,transfers:careers.reduce((s,g)=>s+g.history.length-1,0),observed:[...observed]};assert(observed.has('SILENT'));assert(observed.has('FAILED'));});
check('C D moves upward and higher projects can rebuild downward; offers remain uncertain',()=>{let upward=null,downward=null,ordinaryFailure=null,silent=0;const tiers=new Set();for(const sourceTier of ['D','C','B']){for(let seed=1;seed<=128&&(!upward||!downward||!ordinaryFailure||tiers.size<4);seed++){const base=advance(createGame('Mercado CD público','ST',seed),'PLAN',{tier:sourceTier});const strong=sourceTier!=='B';for(const k of Object.keys(base.skills))base.skills[k]=strong?95:32;base.proficiency=strong?95:40;base.trust=strong?95:48;base.confidence=strong?85:60;base.reputation=strong?60:0;advance(base,'INTEREST',{tier:sourceTier});if(!base.market.length)silent++;for(const id of base.market){tiers.add(byId(id).division);for(let n=1;n<=12;n++){const g=clone(base),from=g.clubId,mode=g.marketModes[id];assert(choose(g,pick(g,'contact:'+id).id));g.rng=(Math.imul(n,2654435761)+17)>>>0;assert(validGame(g));assert(choose(g,g.event.choices[0].id));if(g.event.kind==='ASSESSMENT_RESULT'){assert.equal(g.clubId,from);if(mode==='OFFER')ordinaryFailure??={from,to:id,seed,n};continue;}assert.equal(g.event.kind,'OFFER');const p=clone(g.event.choices[0].profile);assert(p.monthly>0&&p.trainingQuality>0);assert(choose(g,g.event.choices[0].id));assert.equal(g.clubId,id);assert.equal(g.salary,p.monthly);assert.equal(g.clubProject.trainingQuality,p.trainingQuality);calendar(g);if(['C','D'].includes(byId(from).division)&&byId(id).level>byId(from).level)upward??={from,to:id,seed};if(byId(from).division!=='D'&&['C','D'].includes(byId(id).division)&&byId(id).level<byId(from).level)downward??={from,to:id,seed,mode};}}}}assert(upward&&downward&&ordinaryFailure);assert.deepEqual(tiers,new Set(['A','B','C','D']));metrics.market={upward,downward,ordinaryFailure,silent,destinationTiers:[...tiers]};});
check('public frozen06 pending choices keep contractual facts and numeric effects; DONE and factual prefixes immutable',()=>{assert.equal(OLD06.engineSha256,'556268622eea846e1d8b1311ad328e108a47e9f6af2e10354db28064e7deefdf');const rows=[];for(const[k,snapshot]of Object.entries(OLD06.snapshots)){const g=clone(snapshot),raw=JSON.stringify(g),before=clone(g);assert(validGame(g),k);assert.equal(JSON.stringify(g),raw,k+' validation mutation');if(g.phase==='DONE'){assert.equal(choose(g,'forged@'+g.serial),false);assert.equal(JSON.stringify(g),raw);rows.push({kind:k,closed:true});continue;}const effect=OLD06.effects[k];assert(choose(g,effect.id),k);for(const key of ['skills','dna','rng','condition','fatigue','happiness','mentalStress','confidence','trust','pressure','totalstats','seasonStats','playedMatches','objectiveHistory','progression','choicesLog','yearStats','salary','rival','clubProject'])assert.deepEqual(g[key],effect.after[key],k+' pending effect '+key);if(before.season===g.season)assert.deepEqual(g.schedule,effect.after.schedule,k+' current season schedule');if(k==='CONTACT'||k==='REGIONAL_CONTACT')assert.deepEqual(g.event,effect.after.event,k+' pending negotiated offer');finish(g,{move:true});for(const key of ['playedMatches','objectiveHistory','progression','choicesLog','history','yearStats'])assert.deepEqual(g[key].slice(0,before[key].length),before[key],k+' rewrote '+key);rows.push({kind:k,preservedMatches:before.playedMatches.length,finalMatches:g.playedMatches.length});}metrics.compatibility=rows;});
check('explicit continuation clones closed legacy21 saves to25 and replays remaining choices without rewriting facts',()=>{assert.equal(typeof E.extendCareer,'function');const rows=[];for(const key of ['DONE','REGIONAL_DONE']){const old=clone(OLD06.snapshots[key]),raw=JSON.stringify(old),before=clone(old),extended=E.extendCareer(old);assert(extended);assert.notEqual(extended,old);assert.equal(JSON.stringify(old),raw,'explicit continuation mutated source');assert.equal(extended.careerEndAge,25);assert.equal(extended.season,21);assert.equal(extended.nationalRevision,1);assert(validGame(extended));for(const field of ['playedMatches','objectiveHistory','progression','choicesLog','history','yearStats','dna','skills','totalstats'])assert.deepEqual(extended[field],before[field],key+' resume rewrote '+field);const replay=clone(extended);finish(extended,{move:true,marketWindows:5});for(const c of extended.choicesLog.slice(before.choicesLog.length)){const loaded=clone(replay);assert(choose(replay,c.id));assert(choose(loaded,c.id));assert.deepEqual(replay,loaded);}assert.deepEqual(replay,extended);assert.equal(JSON.stringify(old),raw);for(const field of ['playedMatches','objectiveHistory','progression','choicesLog','history','yearStats'])assert.deepEqual(extended[field].slice(0,before[field].length),before[field],key+' resumed future rewrote '+field);rows.push({kind:key,age:extended.age,fixtures:extended.playedMatches.length,seasons:extended.yearStats.length,objectives:extended.objectiveHistory.length,marketWindows:extended.choicesLog.filter(c=>c.kind==='INTEREST').length});}for(const source of [createGame('Não encerrado','ST',7),clone(OLD06.snapshots.PLAN),clone(careers[0]),null]){const raw=JSON.stringify(source);assert.equal(E.extendCareer(source),null);assert.equal(JSON.stringify(source),raw);}const malformed=clone(OLD06.snapshots.DONE);malformed.totalstats.apps++;const badRaw=JSON.stringify(malformed);assert.equal(E.extendCareer(malformed),null);assert.equal(JSON.stringify(malformed),badRaw);metrics.explicitContinuation=rows;});
check('new division markers groups and profile forgeries reject atomically without dropping legacy fields',()=>{const base=advance(createGame('Guarda CD','AM',13),'PLAN',{tier:'D'});const bad=[g=>g.careerEndAge=21,g=>g.careerEndAge=26,g=>g.careerEndAge='25',g=>g.age=26,g=>g.season=25,g=>g.nationalRevision=2,g=>g.scheduleNationalRevision=2,g=>delete g.nationalRevision,g=>g.scheduleGroup='A99',g=>g.scheduleGroup=byId(g.schedule[0]).group==='A1'?'A2':'A1',g=>g.schedule[0]=CLUBS.find(c=>c.division==='C').id,g=>g.scheduleDivision='C',g=>g.clubProject.division='A',g=>g.clubProject.group='A99'];for(const mutate of bad){const x=clone(base);mutate(x);const raw=JSON.stringify(x);assert.equal(validGame(x),false);assert.doesNotThrow(()=>assert.equal(choose(x,x.event.choices[0].id),false));assert.equal(JSON.stringify(x),raw);}const closed25=clone(careers[0]);delete closed25.careerEndAge;const raw25=JSON.stringify(closed25);assert.equal(validGame(closed25),false,'post21 state must retain extended end marker');assert.equal(choose(closed25,'forged@'+closed25.serial),false);assert.equal(JSON.stringify(closed25),raw25);metrics.atomicRejections=bad.length+1;});
const hash=url=>crypto.createHash('sha256').update(fs.readFileSync(url)).digest('hex');const report={groups,metrics,engineSha256:hash(new URL('../prototypes/dez-clubes-v2/engine.mjs',import.meta.url)),catalogSha256:hash(new URL('../prototypes/dez-clubes-v2/clubs.mjs',import.meta.url))};if(process.env.REPORT_FILE)fs.writeFileSync(process.env.REPORT_FILE,JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({groups:groups.length,passed:groups.filter(g=>g.pass).length,metrics},null,2));if(groups.some(g=>!g.pass))process.exitCode=1;
